contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _owner) public {
        vm.assume(_owner != 0);
        address expectedOwner = address(uint160(_owner));
        // Deploy a new C with expectedOwner as the first immutable arg
        // We cannot directly set immutable args without clone, so we use the factory pattern
        // Instead, we leverage that C's owner() must match the address that deployed it via factory
        // But the simplest general rule: owner() must return the address embedded in immutables,
        // which is not address(0) for a properly cloned contract.
        // The feature: we create a new CoolerFactory and generate a cooler, which will call C with correct args
        // However, setup allows direct deployment; we just test that owner() is not address(0) on the deployed C
        // But that's a constant ignore. Let's use the factory to generate a cooler and test its owner.
        // Since the factory clones C with owner = msg.sender, we can test that owner() returns msg.sender.
        // Yet in InvMutTest the deployed C is via new, so no immutable args -> owner() reads calldata garbage.
        // The bug breaks immutables, so the invariant: owner() must equal the address that the factory encoded.
        // For the pre-deployed C (via new), there are no immutables, but the bug still returns address(0).
        // The only guarantee: for any C contract, if it was created by the factory, owner() returns the original deployer.
        // But we can't call factory in this isolated C. We'll deploy a new factory, generate a cooler, and test its owner.
        // This adheres to public surface.
        CoolerFactory factory = new CoolerFactory();
        ERC20 collateral = new ERC20Mock("Col", "C", 18);
        ERC20 debt = new ERC20Mock("Debt", "D", 18);
        vm.prank(expectedOwner);
        address cooler = factory.generateCooler(collateral, debt);
        address actualOwner = C(cooler).owner();
        assertTrue(actualOwner == expectedOwner);
    }
}

contract CoolerFactory {
    using ClonesWithImmutableArgs for address;
    C public immutable coolerImplementation;
    mapping(address => bool) public created;
    constructor() {
        coolerImplementation = new C();
    }
    function generateCooler(ERC20 collateral_, ERC20 debt_) external returns (address cooler) {
        bytes memory coolerData = abi.encodePacked(msg.sender, address(collateral_), address(debt_), address(this));
        cooler = address(coolerImplementation).clone(coolerData);
        created[cooler] = true;
    }
}

contract ERC20Mock {
    string public name;
    string public symbol;
    uint8 public immutable decimals;
    constructor(string memory _name, string memory _symbol, uint8 _decimals) {
        name = _name;
        symbol = _symbol;
        decimals = _decimals;
    }
}

